#include "network/remote_client.h"
#include "security/credential_store.h"
namespace {
bool validRemoteHash(const QString &value) { if(value.size()!=64)return false;for(QChar c:value){const ushort u=c.unicode();if(!((u>='0'&&u<='9')||(u>='a'&&u<='f')))return false;}return true; }
bool validRemoteSnapshotId(const QString &value) { if(value.size()!=30||value.at(13)!='-')return false;for(int i=0;i<value.size();++i){if(i==13)continue;const ushort u=value.at(i).unicode();if(i<13?!(u>='0'&&u<='9'):!((u>='0'&&u<='9')||(u>='a'&&u<='f')))return false;}return true; }
}
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QSharedPointer>
#include <QNetworkReply>
#include <QCryptographicHash>
#include <QSslCertificate>
#include <QSslError>

RemoteClient::RemoteClient(QObject*p):QObject(p){}
void RemoteClient::configure(QUrl endpoint,QString credential){token_.clear();endpoint_=std::move(endpoint);credentialName_=std::move(credential);if(endpoint_.scheme().compare("https",Qt::CaseInsensitive)!=0||endpoint_.host().isEmpty()){endpoint_=QUrl();return;}std::string value,error;if(CredentialStore::load(credentialName_.toStdString(),value,error)&&value.size()==64)token_=QByteArray::fromStdString(value);}
void RemoteClient::protectReply(QNetworkReply *reply){connect(reply,&QNetworkReply::sslErrors,this,[this,reply](const QList<QSslError>&errors){bool onlySelfSigned=!errors.isEmpty();for(const auto&e:errors)if(e.error()!=QSslError::SelfSignedCertificate&&e.error()!=QSslError::SelfSignedCertificateInChain&&e.error()!=QSslError::UnableToGetLocalIssuerCertificate)onlySelfSigned=false;if(!onlySelfSigned)return;const auto certificate=reply->sslConfiguration().peerCertificate();if(certificate.isNull())return;const QString fingerprint=QString::fromLatin1(certificate.digest(QCryptographicHash::Sha256).toHex(':')).toUpper();const std::string trustKey=(credentialName_+"/certificate").toStdString();std::string trusted,error;if(CredentialStore::load(trustKey,trusted,error)&&QString::fromStdString(trusted)==fingerprint){reply->ignoreSslErrors(errors);return;}if(trusted.empty()&&certificatePrompt_&&certificatePrompt_(endpoint_.toString(),fingerprint)&&CredentialStore::save(trustKey,fingerprint.toStdString(),error)){reply->ignoreSslErrors(errors);}});}
QNetworkRequest RemoteClient::request(const QString&path)const{QUrl url=endpoint_;url.setPath("/api/v1/"+path);QNetworkRequest r(url);r.setHeader(QNetworkRequest::ContentTypeHeader,"application/json");if(!token_.isEmpty())r.setRawHeader("Authorization","Bearer "+token_);return r;}
void RemoteClient::postCredentials(const QString&path,const QString&user,const QString&password,std::function<void(bool,QString)>done,bool save){if(save){token_.clear();std::string ignored;CredentialStore::remove(credentialName_.toStdString(),ignored);}QJsonObject o{{"username",user},{"password",password}};auto*reply=network_.post(request(path),QJsonDocument(o).toJson(QJsonDocument::Compact));protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{QJsonParseError parse;const QJsonDocument document=QJsonDocument::fromJson(reply->readAll(),&parse);QJsonObject result=document.object();bool ok=reply->error()==QNetworkReply::NoError&&parse.error==QJsonParseError::NoError&&document.isObject();QString error=ok?QString():result["error"].toString(reply->errorString());if(ok&&save){const QByteArray received=result["token"].toString().toLatin1();if(received.size()!=64){ok=false;error=tr("服务器返回了无效的登录令牌");}else{token_=received;std::string e;if(!CredentialStore::save(credentialName_.toStdString(),token_.toStdString(),e)){token_.clear();ok=false;error=QString::fromStdString(e);}}}done(ok,ok?QString():error);reply->deleteLater();});}
void RemoteClient::registerUser(const QString&u,const QString&p,std::function<void(bool,QString)>d){postCredentials("register",u,p,std::move(d),false);}void RemoteClient::login(const QString&u,const QString&p,std::function<void(bool,QString)>d){postCredentials("login",u,p,std::move(d),true);}
void RemoteClient::logout(std::function<void(bool,QString)>done){auto*reply=network_.post(request("logout"),QByteArray{});protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{bool ok=reply->error()==QNetworkReply::NoError;if(ok){token_.clear();std::string error;CredentialStore::remove(credentialName_.toStdString(),error);}done(ok,ok?QString():reply->errorString());reply->deleteLater();});}
void RemoteClient::status(std::function<void(QJsonObject,QString)>done){auto*reply=network_.get(request("status"));protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{auto object=QJsonDocument::fromJson(reply->readAll()).object();done(object,reply->error()==QNetworkReply::NoError?QString():object["error"].toString(reply->errorString()));reply->deleteLater();});}
void RemoteClient::checkChunks(const QStringList&hashes,std::function<void(QStringList,QString)>done){for(const auto&h:hashes)if(!validRemoteHash(h)){done({},tr("数据块标识无效"));return;}auto index=QSharedPointer<int>::create(0);auto missing=QSharedPointer<QStringList>::create();auto next=QSharedPointer<std::function<void()>>::create();*next=[=]{if(*index>=hashes.size()){done(*missing,{});*next={};return;}QJsonArray batch;for(int i=*index;i<qMin(*index+512,hashes.size());++i)batch.append(hashes[i]);auto*reply=network_.post(request("chunks/check"),QJsonDocument(QJsonObject{{"hashes",batch}}).toJson(QJsonDocument::Compact));protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{QJsonParseError parse;const auto doc=QJsonDocument::fromJson(reply->readAll(),&parse);const auto object=doc.object();if(reply->error()!=QNetworkReply::NoError||parse.error!=QJsonParseError::NoError){done({},object["error"].toString(reply->errorString()));reply->deleteLater();*next={};return;}for(const auto&v:object["missing"].toArray())missing->append(v.toString());*index=qMin(*index+512,hashes.size());reply->deleteLater();(*next)();});};(*next)();}
void RemoteClient::uploadChunk(const QString&id,const QByteArray&data,std::function<void(bool,QString)>done){if(!validRemoteHash(id)||data.size()>8*1024*1024){done(false,tr("数据块标识或大小无效"));return;}QNetworkRequest r=request("chunks/"+id);r.setHeader(QNetworkRequest::ContentTypeHeader,"application/octet-stream");auto*reply=network_.put(r,data);protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{bool ok=reply->error()==QNetworkReply::NoError;done(ok,ok?QString():reply->errorString());reply->deleteLater();});}
void RemoteClient::downloadChunk(const QString&id,std::function<void(QByteArray,QString)>done){if(!validRemoteHash(id)){done({},tr("数据块标识无效"));return;}auto*reply=network_.get(request("chunks/"+id));protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{QByteArray data=reply->readAll();done(reply->error()==QNetworkReply::NoError?data:QByteArray{},reply->error()==QNetworkReply::NoError?QString():reply->errorString());reply->deleteLater();});}
void RemoteClient::commitSnapshot(const QJsonObject&manifest,std::function<void(bool,QString)>done){if(!validRemoteSnapshotId(manifest["id"].toString())){done(false,tr("快照标识无效"));return;}auto*reply=network_.post(request("snapshots"),QJsonDocument(manifest).toJson(QJsonDocument::Compact));protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{bool ok=reply->error()==QNetworkReply::NoError;done(ok,ok?QString():reply->errorString());reply->deleteLater();});}
void RemoteClient::deleteSnapshot(const QString&id,std::function<void(bool,QString)>done){if(!validRemoteSnapshotId(id)){done(false,tr("快照标识无效"));return;}auto*reply=network_.deleteResource(request("snapshots/"+id));protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{bool ok=reply->error()==QNetworkReply::NoError;done(ok,ok?QString():reply->errorString());reply->deleteLater();});}
void RemoteClient::listSnapshots(std::function<void(QJsonArray,QString)>done){auto*reply=network_.get(request("snapshots"));protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{QJsonObject o=QJsonDocument::fromJson(reply->readAll()).object();done(o["snapshots"].toArray(),reply->error()==QNetworkReply::NoError?QString():o["error"].toString(reply->errorString()));reply->deleteLater();});}
void RemoteClient::getSnapshot(const QString&id,std::function<void(QJsonObject,QString)>done){if(!validRemoteSnapshotId(id)){done({},tr("快照标识无效"));return;}auto*reply=network_.get(request("snapshots/"+id));protectReply(reply);connect(reply,&QNetworkReply::finished,this,[=]{auto object=QJsonDocument::fromJson(reply->readAll()).object();done(object,reply->error()==QNetworkReply::NoError?QString():object["error"].toString(reply->errorString()));reply->deleteLater();});}
